      "native": {
        "id": null,
        "value": {
          "jobs": {
            "release-artifact": {
              "runs-on": "ubuntu-latest",
              "steps": [
                {
                  "uses": "actions/checkout@v6"
                },
                {
                  "uses": "actions/setup-python@v6",
                  "with": {
                    "python-version": "3.11"
                  }
                },
                {
                  "name": "Build wheel from declared package metadata",
                  "run": "set -euo pipefail\npython -m pip install --upgrade pip\npython -m pip wheel . --no-deps --wheel-dir dist\n",
                  "shell": "bash"
                },
                {
                  "name": "Install wheel outside source tree and smoke-test public package",
                  "run": "set -euo pipefail\nexpected=$(python - <<'PY'\nimport tomllib\nwith open(\"pyproject.toml\", \"rb\") as handle:\n    print(tomllib.load(handle)[\"project\"][\"version\"])\nPY\n)\nwheel=$(printf '%s\\n' dist/pcea-*.whl)\ntest -f \"$wheel\"\npython -m venv /tmp/pcea-release-smoke\n/tmp/pcea-release-smoke/bin/python -m pip install --no-deps \"$wheel\"\ncd /tmp\nEXPECTED_VERSION=\"$expected\" /tmp/pcea-release-smoke/bin/python - <<'PY'\nimport os\nfrom importlib.metadata import version\nimport pcea\n\nassert version(\"pcea\") == os.environ[\"EXPECTED_VERSION\"]\nassert callable(pcea.encrypt_state)\nassert callable(pcea.decrypt_state)\nassert pcea.PCEAInstance is not None\nPY\n",
                  "shell": "bash"
                }
              ]
            },
            "test": {
              "runs-on": "ubuntu-latest",
              "steps": [
                {
                  "uses": "actions/checkout@v6"
                },
                {
                  "uses": "actions/setup-python@v6",
                  "with": {
                    "python-version": "${{ matrix.python-version }}"
                  }
                },
                {
                  "name": "Install package with dev dependencies",
                  "run": "python -m pip install --upgrade pip\npython -m pip install -e \".[dev]\"\n"
                },
                {
                  "name": "Run full repository test suite",
                  "run": "PYTHONPATH=. python -m pytest -q"
                }
              ],
              "strategy": {
                "matrix": {
                  "python-version": [
                    "3.9",
                    "3.11",
                    "3.13"
                  ]
                }
              }
            }
          },
          "name": "full-suite",
          "on": {
            "pull_request": null,
            "push": {
              "branches": [
                "main"
              ]
            }
          },
          "permissions": {
            "contents": "read"
          }
        }
      },
